// Generated by scripts/emit-typedefs.ts from schema/*.graphql. Do not edit.
export const typeDefs = "# _root.graphql\n# Root types. Every other file extends them, one domain per file (AGENTS.md §16).\ntype Query\ntype Mutation\n\n\"An ISO 8601 date-time, in UTC.\"\nscalar DateTime\n\n\"\"\"\nA rich-text document (Tiptap JSON, schema version 1). Validated by the API on every write; only known node\nand mark types are accepted, and links must be http(s) or mailto.\n\"\"\"\nscalar RichText\n\n\"For cursor pagination: pass endCursor as `after` to get the next page.\"\ntype PageInfo {\n  endCursor: String\n  hasNextPage: Boolean!\n}\n\n\"CEFR levels. An editorial estimate of a lesson's difficulty, not a guarantee of a learner's level.\"\nenum CefrLevel {\n  A1\n  A2\n  B1\n  B2\n  C1\n  C2\n}\n\n# assessment.graphql\n\"\"\"\nExercises as editors write them: a list of sets, each {title, instructions?, questions: [...]}, where a question is\n{type, points?, prompt, options? (single choice), grading, explanation?}. Validated in full by the API; see\napps/api/src/modules/assessment/schemas.ts for the exact shape of each question type. Editorial only.\n\"\"\"\nscalar ExercisePayload\n\nenum QuestionType {\n  SINGLE_CHOICE\n  TRUE_FALSE_NOT_GIVEN\n  GAP_FILL\n  MULTIPLE_CHOICE\n  YES_NO_NOT_GIVEN\n  MATCHING\n  COMPLETION\n  SHORT_ANSWER\n}\n\nenum Judgement {\n  TRUE\n  FALSE\n  NOT_GIVEN\n  YES\n  NO\n}\n\nenum MatchingVariant {\n  HEADINGS\n  INFORMATION\n  FEATURES\n  SENTENCE_ENDINGS\n}\n\nenum CompletionVariant {\n  SENTENCE\n  SUMMARY\n  NOTE\n}\n\n\"A question as the learner sees it. Answers are never part of it: they come back from gradePractice.\"\ninterface Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n}\n\ntype QuestionOption {\n  id: ID!\n  content: String!\n}\n\ntype SingleChoiceQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  stem: String!\n  options: [QuestionOption!]!\n}\n\ntype TrueFalseNotGivenQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  statement: String!\n}\n\ntype TextSegment {\n  text: String!\n}\n\ntype GapSegment {\n  gapId: String!\n}\n\nunion GapFillSegment = TextSegment | GapSegment\n\ntype GapFillQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  segments: [GapFillSegment!]!\n}\n\n\"Choose TWO (or more) letters: one mark per correct letter.\"\ntype MultipleChoiceQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  stem: String!\n  choose: Int!\n  options: [QuestionOption!]!\n}\n\n\"Do the statements agree with the views of the writer?\"\ntype YesNoNotGivenQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  statement: String!\n}\n\ntype MatchingItem {\n  itemId: String!\n  text: String!\n}\n\n\"Match each item (paragraph, statement, sentence beginning) to one option. One mark per item.\"\ntype MatchingQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  variant: MatchingVariant!\n  items: [MatchingItem!]!\n  options: [QuestionOption!]!\n  \"An option may be the answer for more than one item.\"\n  reuse: Boolean!\n}\n\n\"Complete the sentences, summary or notes: one mark per gap, answers within the word limit.\"\ntype CompletionQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  variant: CompletionVariant!\n  segments: [GapFillSegment!]!\n  \"NO MORE THAN this many WORDS.\"\n  wordLimit: Int!\n  \"When set, answers are chosen from these words.\"\n  wordBox: [String!]\n}\n\ntype ShortAnswerQuestion implements Question {\n  id: ID!\n  type: QuestionType!\n  position: Int!\n  points: Int!\n  question: String!\n  wordLimit: Int!\n}\n\ntype ExerciseSet {\n  id: ID!\n  title: String!\n  instructions: String\n  questions: [Question!]!\n}\n\ninput GapAnswerInput {\n  gapId: String!\n  text: String!\n}\n\ninput MatchAnswerInput {\n  itemId: String!\n  optionId: ID!\n}\n\n\"\"\"\nOne answer: optionId (single choice), optionIds (multiple choice), judgement (TFNG, YNNG), matches (matching),\ngaps (gap fill, completion) or text (short answer).\n\"\"\"\ninput PracticeAnswerInput {\n  questionId: ID!\n  optionId: ID\n  optionIds: [ID!]\n  judgement: Judgement\n  matches: [MatchAnswerInput!]\n  gaps: [GapAnswerInput!]\n  text: String\n}\n\ninput GradePracticeInput {\n  exerciseSetId: ID!\n  \"At most 100.\"\n  answers: [PracticeAnswerInput!]!\n}\n\ntype ChoiceAnswer {\n  optionId: ID!\n}\n\ntype JudgementAnswer {\n  judgement: Judgement!\n}\n\ntype GapAnswer {\n  gapId: String!\n  \"The first accepted answer.\"\n  text: String!\n}\n\ntype GapsAnswer {\n  gaps: [GapAnswer!]!\n}\n\ntype ChoicesAnswer {\n  optionIds: [ID!]!\n}\n\ntype MatchAnswer {\n  itemId: String!\n  optionId: ID!\n}\n\ntype MatchesAnswer {\n  matches: [MatchAnswer!]!\n}\n\ntype TextAnswer {\n  \"The first accepted answer.\"\n  text: String!\n}\n\nunion CorrectAnswer = ChoiceAnswer | ChoicesAnswer | JudgementAnswer | MatchesAnswer | GapsAnswer | TextAnswer\n\ntype QuestionResult {\n  questionId: ID!\n  correct: Boolean!\n  awardedPoints: Int!\n  maxPoints: Int!\n  explanation: String\n  correctAnswer: CorrectAnswer!\n}\n\ntype PracticeResult {\n  exerciseSetId: ID!\n  score: Int!\n  maxScore: Int!\n  questions: [QuestionResult!]!\n}\n\nextend type Query {\n  \"A published exercise set on this site.\"\n  exerciseSet(id: ID!): ExerciseSet\n}\n\nextend type Mutation {\n  \"Grades answers on the server. Nothing is stored: practice is anonymous in the MVP.\"\n  gradePractice(input: GradePracticeInput!): PracticeResult!\n}\n\n# --- Suggested questions (editorial: drafted by the local language model from a draft's script)\n\nenum QuestionSuggestionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\n\"A drafted question, answer key included, for an editor to check. Approving adds it to the draft's exercises.\"\ntype QuestionSuggestion {\n  id: ID!\n  status: QuestionSuggestionStatus!\n  type: QuestionType!\n  \"The question as editors write it (prompt, options, grading, explanation): the same shape as ExercisePayload.\"\n  question: ExercisePayload!\n}\n\ntype QuestionSuggestions {\n  \"Same states as vocabulary suggestions.\"\n  state: VocabularySuggestionsState!\n  \"False when the language model wasn't reachable (no questions can be drafted without it).\"\n  usedLanguageModel: Boolean\n  items: [QuestionSuggestion!]!\n}\n\nextend type Revision {\n  \"Editorial: questions drafted for this draft's current script.\"\n  questionSuggestions: QuestionSuggestions!\n}\n\nextend type Mutation {\n  \"Editors: add the chosen drafted questions to the draft's exercises (one set per question type).\"\n  approveQuestionSuggestions(localizationId: ID!, lockVersion: Int!, ids: [ID!]!): EditorialResource!\n  \"Editors: take drafted questions off the list.\"\n  rejectQuestionSuggestions(localizationId: ID!, ids: [ID!]!): Boolean!\n  \"Editors: draft questions about the draft's saved script (it needs a few sentences). Runs in the background.\"\n  suggestQuestions(localizationId: ID!): Boolean!\n}\n\n# audio.graphql\nenum AudioTrackStatus {\n  GENERATING\n  READY\n  APPROVED\n  FAILED\n}\n\nenum VoiceGender {\n  MALE\n  FEMALE\n}\n\nenum VoiceAccent {\n  US\n  UK\n}\n\n\"When a word is spoken in a track: its block, code-point offsets in that block's text, and milliseconds.\"\ntype WordTiming {\n  blockId: String!\n  start: Int!\n  end: Int!\n  startMs: Int!\n  endMs: Int!\n}\n\nenum VoiceoverMode {\n  \"One voice reads the whole text.\"\n  SINGLE\n  \"Each HOST1/HOST2 turn is read by its host's voice, like a podcast.\"\n  CONVERSATION\n}\n\n\"A host's voice in a conversation voice-over.\"\ntype TrackSpeaker {\n  host: Int!\n  voiceId: ID!\n  voiceName: String!\n}\n\n\"Host names learners see instead of HOST1 and HOST2.\"\ntype SpeakerNames {\n  host1: String\n  host2: String\n}\n\ninput SpeakerNamesInput {\n  host1: String\n  host2: String\n}\n\ninput ConversationHostInput {\n  voiceId: ID!\n  \"Shown to learners instead of HOST1/HOST2 (saved on the draft).\"\n  name: String\n}\n\ninput ConversationVoiceoverInput {\n  localizationId: ID!\n  \"eleven_v3 (the default) or eleven_v3_conversational.\"\n  modelId: String!\n  host1: ConversationHostInput!\n  host2: ConversationHostInput!\n}\n\n\"A voice reading a revision's text: one voice, or two hosts in a conversation.\"\ntype AudioTrack {\n  id: ID!\n  status: AudioTrackStatus!\n  mode: VoiceoverMode!\n  \"Both hosts' voices, for conversations; empty for a single voice.\"\n  speakers: [TrackSpeaker!]!\n  modelId: String\n  voiceName: String!\n  gender: VoiceGender!\n  accent: VoiceAccent!\n  \"For learners: \\\"Woman · UK\\\", or \\\"Conversation · Kate & Max\\\".\"\n  label: String!\n  \"A time-limited address for the audio file, once it exists.\"\n  url: String\n  durationMs: Int\n  \"Empty when the provider gave no timings: they're never invented.\"\n  wordTimings: [WordTiming!]!\n  characters: Int!\n  \"Editorial: the text changed after this voice-over was made.\"\n  stale: Boolean!\n  error: String\n  createdAt: DateTime!\n}\n\ntype Voice {\n  id: ID!\n  name: String!\n  gender: VoiceGender!\n  accent: VoiceAccent!\n  previewUrl: String\n}\n\ntype VoiceCatalog {\n  \"elevenlabs, or fake when no key is set.\"\n  provider: String!\n  voices: [Voice!]!\n  charactersUsed: Int\n  charactersLimit: Int\n}\n\nextend type Query {\n  \"Editorial: voices to choose from (US and UK, man or woman) and this month's character use.\"\n  voiceCatalog(siteId: ID!): VoiceCatalog!\n}\n\nextend type Mutation {\n  \"Editors: start a voice-over of the draft's text for each voice (at most 4 at a time). Runs in the background.\"\n  requestVoiceovers(localizationId: ID!, voiceIds: [ID!]!): [AudioTrack!]!\n  \"Editors: one voice-over of the draft's HOST1/HOST2 conversation, each host with their own voice.\"\n  requestConversationVoiceover(input: ConversationVoiceoverInput!): [AudioTrack!]!\n  \"Editors: keep a finished voice-over; only approved ones go live.\"\n  approveAudioTrack(id: ID!): AudioTrack!\n  deleteAudioTrack(id: ID!): Boolean!\n}\n\n# --- The Python worker (authenticated with its own service token, never an editor's session)\n\n\"Job data, validated per job type by the API.\"\nscalar JobPayload\n\ntype ClaimedJob {\n  id: ID!\n  type: String!\n  payload: JobPayload!\n  claimToken: String!\n  attempt: Int!\n}\n\ntype MediaUpload {\n  objectKey: String!\n  uploadUrl: String!\n}\n\nextend type Mutation {\n  claimJob(types: [String!]!): ClaimedJob\n  createJobUpload(jobId: ID!, claimToken: String!, contentType: String!): MediaUpload!\n  completeJob(jobId: ID!, claimToken: String!, result: JobPayload!): Boolean!\n  failJob(jobId: ID!, claimToken: String!, error: String!, retryable: Boolean!): Boolean!\n}\n\n# health.graphql\n\"Whether a part of the system is working.\"\nenum HealthStatus {\n  OK\n  DOWN\n}\n\n\"The API's own view of its health. Public: it reveals no hostnames, versions of dependencies or errors.\"\ntype Health {\n  status: HealthStatus!\n  database: HealthStatus!\n}\n\nextend type Query {\n  health: Health!\n}\n\n# identity.graphql\nenum SiteRole {\n  OWNER\n  ADMIN\n  EDITOR\n  REVIEWER\n  VIEWER\n}\n\ntype Site {\n  id: ID!\n  domain: String!\n  name: String!\n  defaultLocale: String!\n}\n\ntype Membership {\n  site: Site!\n  role: SiteRole!\n}\n\n\"The signed-in editor. Learners have no accounts until a later phase.\"\ntype Viewer {\n  id: ID!\n  email: String!\n  name: String\n  memberships: [Membership!]!\n}\n\nextend type Query {\n  \"Who is signed in (from the request's session token), or null.\"\n  viewer: Viewer\n}\n\n# lexical-items.graphql\n# --- A lesson's own lexical vocabulary (ADR 0010): items from the editor's list, explained for IELTS learners.\n\nenum LexicalItemKind {\n  KEYWORD\n  COLLOCATION\n  IDIOM\n  PHRASAL_VERB\n  \"A sentence structure or grammar pattern.\"\n  STRUCTURE\n  \"A paraphrase: other words for the same idea, as IELTS questions reword the passage.\"\n  PARAPHRASE\n}\n\nenum LexicalItemStatus {\n  \"Waiting for the local language model to explain it.\"\n  PENDING\n  \"Explained by the model, waiting for an editor.\"\n  DRAFT\n  \"Checked by an editor: learners see it once the lesson is published.\"\n  APPROVED\n}\n\ntype LexicalItem {\n  id: ID!\n  \"The item as the editor listed it.\"\n  text: String!\n  \"The editor's note from the list, if any.\"\n  note: String\n  kind: LexicalItemKind\n  \"The item's words as the script has them (… where they're split apart).\"\n  quote: String\n  meaning: String\n  synonyms: [String!]!\n  example: String\n  ieltsTip: String\n  status: LexicalItemStatus!\n  \"The script's sentence with the item, found in the current script; null when it isn't there.\"\n  inText: String\n}\n\ntype DraftLexicalItems {\n  \"The latest explaining job: same states as vocabulary suggestions.\"\n  state: VocabularySuggestionsState!\n  \"False when the language model wasn't reachable (nothing can be explained without it).\"\n  usedLanguageModel: Boolean\n  items: [LexicalItem!]!\n}\n\nextend type Revision {\n  \"Editorial: the lesson's lexical vocabulary, in list order.\"\n  lexicalItems: DraftLexicalItems!\n}\n\n\"An approved item of a published lesson, for the learner's Lexical Vocabulary tab.\"\ntype PublicLexicalItem {\n  id: ID!\n  text: String!\n  kind: LexicalItemKind!\n  meaning: String!\n  synonyms: [String!]!\n  example: String\n  ieltsTip: String\n  inText: String\n}\n\nextend type ReadingResource {\n  \"Approved lexical vocabulary, in list order.\"\n  lexicalItems: [PublicLexicalItem!]!\n}\n\ntype LexicalListAdded {\n  added: Int!\n  \"Items already in the lesson's list (or repeated in this one).\"\n  skipped: Int!\n}\n\ninput LexicalItemApproval {\n  id: ID!\n  kind: LexicalItemKind!\n  meaning: String!\n  synonyms: [String!]!\n  example: String\n  ieltsTip: String\n}\n\nextend type Mutation {\n  \"Editors: add items from a list (one per line; a note may follow a spaced dash). The local AI explains them.\"\n  addLexicalList(localizationId: ID!, list: String!): LexicalListAdded!\n  \"Editors: explain items still waiting (redoDrafts: unapproved ones too). In the background.\"\n  explainLexicalItems(localizationId: ID!, redoDrafts: Boolean = false): Boolean!\n  \"Editors: approve items, with their edits. Returns how many were approved.\"\n  approveLexicalItems(localizationId: ID!, items: [LexicalItemApproval!]!): Int!\n  \"Editors: remove items from the lesson's list. Returns how many were removed.\"\n  deleteLexicalItems(localizationId: ID!, ids: [ID!]!): Int!\n}\n\n# lexicon.graphql\nenum LexicalEntryKind {\n  WORD\n  PHRASE\n  COLLOCATION\n  IDIOM\n  PHRASAL_VERB\n  \"A grammar or sentence pattern, e.g. \\\"If I were you, I'd + verb\\\". Learners add it whole.\"\n  SENTENCE_PATTERN\n}\n\n\"The meaning in another language.\"\ntype Translation {\n  \"BCP 47 language, e.g. vi or pt-BR.\"\n  locale: String!\n  text: String!\n}\n\ninput TranslationInput {\n  locale: String!\n  text: String!\n}\n\n\"Where a vocabulary item appears in a text: a span of one block, and the sentence around it.\"\ntype TextOccurrence {\n  blockId: String!\n  \"Unicode code-point offsets into the block's text.\"\n  start: Int!\n  end: Int!\n  text: String!\n  sentence: String!\n}\n\n\"\"\"\nA word or structure a text links to, as learners choose it: the exact sense revision the text pinned, whether the\neditor marked it a key word, and every place it appears (a split pattern has several).\n\"\"\"\ntype VocabularyItem {\n  sense: LexicalSense!\n  isKey: Boolean!\n  occurrences: [TextOccurrence!]!\n}\n\ntype LexicalExample {\n  sentence: String!\n  explanation: String\n}\n\ntype Pronunciation {\n  \"BCP 47 accent label, e.g. en-GB or en-US.\"\n  accent: String!\n  ipa: String!\n}\n\n\"One meaning of a headword, as one exact revision.\"\ntype LexicalSense {\n  id: ID!\n  senseKey: String!\n  partOfSpeech: String!\n  revisionId: ID!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  examples: [LexicalExample!]!\n  pronunciations: [Pronunciation!]!\n  translations: [Translation!]!\n  entry: LexicalEntry!\n}\n\ntype LexicalEntry {\n  id: ID!\n  displayForm: String!\n  kind: LexicalEntryKind!\n  language: String!\n  \"Published senses only.\"\n  senses: [LexicalSense!]!\n}\n\nextend type Query {\n  \"Exact and fuzzy headword lookup. Only entries with a published sense. `first` is at most 50.\"\n  lexicalSearch(query: String!, first: Int! = 20): [LexicalEntry!]!\n  lexicalEntryById(id: ID!): LexicalEntry\n}\n\n# --- Editorial\n\ntype SenseRevision {\n  id: ID!\n  revisionNo: Int!\n  status: RevisionStatus!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  lockVersion: Int!\n  examples: [LexicalExample!]!\n  pronunciations: [Pronunciation!]!\n  translations: [Translation!]!\n  publishedAt: DateTime\n}\n\ntype EditorialSense {\n  id: ID!\n  site: Site!\n  senseKey: String!\n  partOfSpeech: String!\n  entry: LexicalEntry!\n  draft: SenseRevision\n  published: SenseRevision\n}\n\ninput LexicalExampleInput {\n  sentence: String!\n  explanation: String\n}\n\ninput PronunciationInput {\n  accent: String!\n  ipa: String!\n}\n\n\"\"\"\nCreates a sense (and its entry, given headword and kind), or edits a sense's draft. Editing a sense with no\ndraft starts a new draft revision; the published one is never changed.\n\"\"\"\ninput ManageLexicalSenseInput {\n  siteId: ID!\n  \"An existing sense to edit. Omit to create one.\"\n  senseId: ID\n  \"For a new sense: its entry, or headword + kind to create one.\"\n  entryId: ID\n  headword: String\n  kind: LexicalEntryKind\n  partOfSpeech: String!\n  senseKey: String!\n  definition: String!\n  cefrLevel: CefrLevel\n  usageNote: String\n  register: String\n  examples: [LexicalExampleInput!]! = []\n  pronunciations: [PronunciationInput!]! = []\n  translations: [TranslationInput!]! = []\n  \"Required when editing an existing draft.\"\n  lockVersion: Int\n}\n\nextend type Query {\n  \"Editorial: the site's word bank, drafts included, optionally filtered by headword (at most 200).\"\n  editorialSenses(siteId: ID!, query: String, first: Int! = 100): [EditorialSense!]!\n  \"Editorial: one sense with its draft and published revisions.\"\n  editorialSense(id: ID!): EditorialSense\n}\n\nextend type Mutation {\n  manageLexicalSense(input: ManageLexicalSenseInput!): EditorialSense!\n  publishLexicalSense(senseId: ID!, lockVersion: Int!): EditorialSense!\n}\n\n# --- Vocabulary suggestions (editorial: words and structures found in a draft's script)\n\nenum VocabularySuggestionStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum VocabularySuggestionsState {\n  \"Nothing asked yet for this script (the Suggest button starts it).\"\n  IDLE\n  \"The worker is looking (with the local language model this can take a few minutes).\"\n  WORKING\n  DONE\n  \"The worker couldn't finish; ask again.\"\n  FAILED\n}\n\ntype VocabularySuggestion {\n  id: ID!\n  status: VocabularySuggestionStatus!\n  kind: LexicalEntryKind!\n  \"The base form for the word bank: give up, a piece of cake, like + verb-ing.\"\n  displayForm: String!\n  partOfSpeech: String!\n  \"As it appears in the script.\"\n  surfaceText: String!\n  sentence: String!\n  \"A draft meaning from the language model, to check; null when none was made.\"\n  definition: String\n  cefrLevel: CefrLevel\n  \"Already in the word bank (published), so approving only links it.\"\n  inWordBank: Boolean!\n  \"nlp (word frequency) or ai (the language model).\"\n  source: String!\n}\n\ntype VocabularySuggestions {\n  state: VocabularySuggestionsState!\n  \"False when the language model wasn't reachable (only word-frequency suggestions); null before the first run.\"\n  usedLanguageModel: Boolean\n  items: [VocabularySuggestion!]!\n}\n\nextend type Revision {\n  \"Editorial: suggested vocabulary for this draft's current text.\"\n  vocabularySuggestions: VocabularySuggestions!\n}\n\nextend type Mutation {\n  \"Editors: link the chosen suggestions in the text as key words (new items are added to the word bank as drafts).\"\n  approveVocabularySuggestions(localizationId: ID!, lockVersion: Int!, ids: [ID!]!): EditorialResource!\n  \"Editors: take suggestions off the list (they aren't suggested again for this lesson).\"\n  rejectVocabularySuggestions(localizationId: ID!, ids: [ID!]!): Boolean!\n  \"Editors: look for vocabulary in the draft's saved script (its text must not be empty). Runs in the background.\"\n  suggestVocabulary(localizationId: ID!): Boolean!\n  \"The worker: keep a long job claimed.\"\n  renewJobLease(jobId: ID!, claimToken: String!): Boolean!\n}\n\n# resources.graphql\nenum ResourceKind {\n  READING\n  LISTENING\n  LEXICAL_COLLECTION\n  ARTICLE\n}\n\nenum RevisionStatus {\n  DRAFT\n  IN_REVIEW\n  PUBLISHED\n  SUPERSEDED\n}\n\ntype Topic {\n  id: ID!\n  slug: String!\n  name: String!\n  description: String\n}\n\ntype ExamLabel {\n  id: ID!\n  code: String!\n  name: String!\n}\n\n\"A published lesson or article, as learners see it. Always one exact, frozen revision.\"\ninterface Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ntype ReadingResource implements Resource {\n  \"Conversation lessons: the names shown instead of HOST1/HOST2.\"\n  speakerNames: SpeakerNames\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n  \"The word senses the text links to (its `lexical` marks), at the exact revisions it pinned.\"\n  vocabulary: [LexicalSense!]!\n  \"The same links as learners choose them: one item per word or structure, with key flags and sentences.\"\n  vocabularyItems: [VocabularyItem!]!\n  \"Approved voice-overs, each with its voice tags and word timings.\"\n  audioTracks: [AudioTrack!]!\n  wordCount: Int!\n  \"At about 200 words a minute.\"\n  estimatedReadingSeconds: Int!\n}\n\ntype ListeningResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  \"The transcript. Audio tracks and timings arrive in Phase 3.\"\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ntype LexicalCollectionResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n  \"The words, pinned to the exact sense revisions chosen when the collection was published.\"\n  items: [LexicalSense!]!\n}\n\ntype ArticleResource implements Resource {\n  id: ID!\n  kind: ResourceKind!\n  locale: String!\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  revisionNo: Int!\n  publishedAt: DateTime!\n  topics: [Topic!]!\n  examLabels: [ExamLabel!]!\n  exerciseSets: [ExerciseSet!]!\n}\n\ninput ResourceFilter {\n  kind: ResourceKind\n  cefrLevel: CefrLevel\n  topicSlug: String\n  \"Defaults to the site's default locale.\"\n  locale: String\n  \"Full-text search in titles, summaries and text.\"\n  search: String\n}\n\ntype ResourceConnection {\n  nodes: [Resource!]!\n  pageInfo: PageInfo!\n}\n\nextend type Query {\n  \"Published resources on this site, newest first. `first` is at most 50.\"\n  publishedResources(filter: ResourceFilter, first: Int! = 20, after: String): ResourceConnection!\n  resourceBySlug(kind: ResourceKind!, slug: String!, locale: String): Resource\n  topics: [Topic!]!\n\n  \"Editorial: a resource with its draft and published revisions. Members of its site only.\"\n  editorialResource(id: ID!): EditorialResource\n  \"Editorial: a site's resources, newest first (at most 100).\"\n  editorialResources(siteId: ID!, first: Int! = 50): [EditorialResource!]!\n  \"Editorial: whether a web address is free on the site, and the first free one like it (sasas, sasas-2...).\"\n  slugAvailability(siteId: ID!, slug: String!): SlugAvailability!\n}\n\n# --- Editorial\n\n\"The four parts of a reading lesson.\"\nenum LessonPart {\n  SCRIPT\n  VOICEOVER\n  VOCABULARY\n  QUESTIONS\n}\n\n\"Which parts of a lesson are finished. Review and publishing wait until none is missing.\"\ntype LessonChecklist {\n  \"The text isn't empty.\"\n  script: Boolean!\n  \"An approved voice-over that still matches the text.\"\n  voiceover: Boolean!\n  \"At least one word or phrase linked.\"\n  vocabulary: Boolean!\n  \"At least one question.\"\n  questions: Boolean!\n  \"Required parts that aren't finished yet.\"\n  missing: [LessonPart!]!\n}\n\ntype Revision {\n  \"Editorial: which parts are finished.\"\n  checklist: LessonChecklist!\n  speakerNames: SpeakerNames\n  id: ID!\n  revisionNo: Int!\n  status: RevisionStatus!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText!\n  topics: [Topic!]!\n  \"The linked word senses, as in the text.\"\n  vocabulary: [LexicalSense!]!\n  vocabularyItems: [VocabularyItem!]!\n  \"Every voice-over of this revision, in any state.\"\n  audioTracks: [AudioTrack!]!\n  \"The exercises, answer keys included, in the shape saveExerciseSets takes. Editors only.\"\n  exercises: ExercisePayload!\n  \"Pass this back when you change the revision; a mismatch means someone else changed it first.\"\n  lockVersion: Int!\n  createdAt: DateTime!\n  updatedAt: DateTime!\n  submittedAt: DateTime\n  publishedAt: DateTime\n}\n\ntype EditorialLocalization {\n  id: ID!\n  locale: String!\n  slug: String!\n  draft: Revision\n  published: Revision\n}\n\ntype EditorialResource {\n  id: ID!\n  kind: ResourceKind!\n  site: Site!\n  createdAt: DateTime!\n  archivedAt: DateTime\n  localizations: [EditorialLocalization!]!\n}\n\ninput CreateResourceInput {\n  speakerNames: SpeakerNamesInput\n  siteId: ID!\n  kind: ResourceKind!\n  locale: String! = \"en\"\n  slug: String!\n  title: String!\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText\n  topicSlugs: [String!]\n}\n\ninput UpdateDraftInput {\n  \"Set to replace the host names; null fields clear a name.\"\n  speakerNames: SpeakerNamesInput\n  localizationId: ID!\n  lockVersion: Int!\n  title: String\n  summary: String\n  cefrLevel: CefrLevel\n  body: RichText\n  \"Replaces the draft's topics.\"\n  topicSlugs: [String!]\n}\n\nextend type Mutation {\n  \"Editors: a new resource with its first draft.\"\n  createResource(input: CreateResourceInput!): EditorialResource!\n  \"Editors: a new draft copied from the published revision (exercises included).\"\n  startDraft(localizationId: ID!): EditorialResource!\n  updateDraft(input: UpdateDraftInput!): EditorialResource!\n  \"Editors: hand the draft to a reviewer.\"\n  submitForReview(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Reviewers: send it back to the editor.\"\n  returnToDraft(localizationId: ID!, lockVersion: Int!, note: String): EditorialResource!\n  \"Reviewers: publish the reviewed draft. The previous published revision is superseded, never changed.\"\n  publishResource(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Editors: replace the draft's exercises. Validated as a whole.\"\n  saveExerciseSets(localizationId: ID!, lockVersion: Int!, sets: ExercisePayload!): EditorialResource!\n  \"Admins and owners: publish a draft straight away, without the review queue. Recorded in the audit log.\"\n  publishNow(localizationId: ID!, lockVersion: Int!): EditorialResource!\n  \"Admins: take the resource off the site. Its revisions are kept.\"\n  archiveResource(resourceId: ID!): EditorialResource!\n}\n\ntype SlugAvailability {\n  available: Boolean!\n  \"A free address like the one asked for: the same one when it's free.\"\n  suggestion: String!\n}\n\n# translations.graphql\n# --- Sentence translations for bilingual reading (ADR 0009). Text only: no voice-over.\n\nenum TranslationStatus {\n  \"Made by the local language model, waiting for an editor.\"\n  DRAFT\n  \"Checked by an editor: learners see it once the lesson is published.\"\n  APPROVED\n}\n\ntype SentenceTranslation {\n  id: ID!\n  text: String!\n  status: TranslationStatus!\n}\n\n\"One sentence of a draft's script (code-point offsets into its block), with its translation if it has one.\"\ntype TranslationSentence {\n  blockId: String!\n  start: Int!\n  end: Int!\n  source: String!\n  translation: SentenceTranslation\n}\n\ntype DraftTranslations {\n  \"vi, fr or de.\"\n  locale: String!\n  \"The latest translation job for this language: same states as vocabulary suggestions.\"\n  state: VocabularySuggestionsState!\n  \"False when the language model wasn't reachable (nothing can be translated without it).\"\n  usedLanguageModel: Boolean\n  sentences: [TranslationSentence!]!\n}\n\nextend type Revision {\n  \"Editorial: the draft's sentences in one language (vi, fr or de), with their translations.\"\n  translations(locale: String!): DraftTranslations!\n}\n\ninput TranslationApproval {\n  id: ID!\n  \"The text to keep: the drafted one, or the editor's edit.\"\n  text: String!\n}\n\n\"An approved translation of one sentence of a published lesson.\"\ntype PublicTranslation {\n  locale: String!\n  blockId: String!\n  start: Int!\n  end: Int!\n  text: String!\n}\n\nextend type ReadingResource {\n  \"Approved sentence translations, every language.\"\n  translations: [PublicTranslation!]!\n}\n\nextend type Mutation {\n  \"Editors: translate the draft's sentences that have none yet (redoDrafts: unapproved ones too). In the background.\"\n  translateDraft(localizationId: ID!, locale: String!, redoDrafts: Boolean = false): Boolean!\n  \"Editors: approve translations, with their edits. Returns how many were approved.\"\n  approveTranslations(localizationId: ID!, items: [TranslationApproval!]!): Int!\n}\n";
